"use client";

import "./avatar.css";

import { useState, type ComponentProps } from "react";
import { cx } from "./cx";

export type AvatarProps = ComponentProps<"span"> & {
  size?: "sm" | "md" | undefined;
};

export type AvatarImageProps = ComponentProps<"img">;

export type AvatarFallbackProps = ComponentProps<"span">;

export function Avatar({ size = "md", className, ...rest }: AvatarProps) {
  return (
    <span
      className={cx("ns-avatar", className)}
      data-size={size === "md" ? undefined : size}
      {...rest}
    />
  );
}

export function AvatarImage({ className, onError, ...rest }: AvatarImageProps) {
  const [failed, setFailed] = useState(false);
  if (failed) return null;
  return (
    <img
      className={cx("ns-avatar__image", className)}
      onError={(event) => {
        setFailed(true);
        onError?.(event);
      }}
      {...rest}
    />
  );
}

export function AvatarFallback({ className, ...rest }: AvatarFallbackProps) {
  return <span className={cx("ns-avatar__fallback", className)} {...rest} />;
}

@layer components {
  .ns-avatar {
    position: relative;
    display: inline-grid;
    place-items: center;
    overflow: hidden;
    width: 2rem;
    height: 2rem;
    border: 1px solid
      var(--line, color-mix(in srgb, var(--text-heading, #111) 18%, transparent));
    border-radius: 999px;
    background: var(--bg-hover, #f3f2f1);
    color: var(--text-sub, #767676);
    font-size: var(--type-sm, 0.8rem);
    font-weight: var(--weight-medium, 500);
    line-height: 1;
    vertical-align: middle;
  }

  .ns-avatar[data-size="sm"] {
    width: 1.5rem;
    height: 1.5rem;
    font-size: var(--type-xs, 0.64rem);
  }

  .ns-avatar__image {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  .ns-avatar__fallback {
    display: grid;
    place-items: center;
  }
}
